const boDau = s => String(s).normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/đ/g, 'd').replace(/Đ/g, 'D');
msg.payload = { type: 'msg', text: boDau(msg.payload).slice(0, 150), sec: 10 };
return msg;

const boDau = s => String(s).normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/đ/g, 'd').replace(/Đ/g, 'D');
msg.payload = { type: 'subject', name: boDau(msg.payload).slice(0, 22) };
return msg;

const p = msg.payload;
const c1 = '52b574d6abab6b56';
const c2 = '2ee8af9ddaae60e6';
if (p === 'Gửi thời khóa biểu trên lớp') {
  msg.payload = { groups: { show: [c2], hide: [c1] } };
} else {
  msg.payload = { groups: { show: [c1], hide: [c2] } };
}
return msg;

const boDau = s => String(s).normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '').replace(/đ/g, 'd').replace(/Đ/g, 'D');
const text = String(flow.get('loiNhan') || '').trim();
if (!text) { node.warn('Lời nhắn rỗng, không gửi'); return null; }
msg.payload = { type: 'msg', text: boDau(text).slice(0, 120), sec: 10 };
return msg;

const boDau = s => String(s).normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '').replace(/đ/g, 'd').replace(/Đ/g, 'D');
if (!msg.payload) return null;
msg.payload = { type: 'subject', name: boDau(msg.payload).slice(0, 22) };
return msg;

// Tuần này = Thứ 2..CN; Tháng này = ngày 1..cuối tháng (giờ VN).
// So sánh với CÙNG KỲ trước đó (tuần trước: Thứ 2..cùng thứ hôm nay).
let kind = flow.get('tkKind') || 'tuan';
if (msg.payload === 'tuan' || msg.payload === 'thang') kind = msg.payload;
flow.set('tkKind', kind);
const DAY = 86400000;
const vn = new Date(Date.now() + 7 * 3600000);              // getUTC* = giờ VN
const y = vn.getUTCFullYear(), mo = vn.getUTCMonth(), dd = vn.getUTCDate();
const today = Date.UTC(y, mo, dd);
let A, B, PA, PB;
if (kind === 'tuan') {
  A = today - ((vn.getUTCDay() + 6) % 7) * DAY;             // Thứ 2
  B = A + 6 * DAY;
  PA = A - 7 * DAY; PB = today - 7 * DAY;
} else {
  A = Date.UTC(y, mo, 1); B = Date.UTC(y, mo + 1, 0);
  PA = Date.UTC(y, mo - 1, 1);
  PB = Date.UTC(y, mo - 1, Math.min(dd, new Date(Date.UTC(y, mo, 0)).getUTCDate()));
}
const d = t => new Date(t).toISOString().slice(0, 10);
const t0 = t => encodeURIComponent(d(t) + 'T00:00:00+07:00');
const reqId = Date.now();
flow.set('tkReq', { id: reqId, kind, A: d(A), B: d(B), got: {} });
const key = env.get('SUPABASE_KEY');
const headers = { apikey: key, Authorization: 'Bearer ' + key };
const r = `day=gte.${d(A)}&day=lte.${d(B)}`;
const q = {
  daily:   `v_daily_minutes?select=day,minutes&${r}`,
  subject: `v_subject_minutes?select=subject,minutes&${r}`,
  pva:     `v_plan_vs_actual?select=day,planned,actual&${r}`,
  lux:     `v_lux_hourly?select=hour,lux_avg&${r}`,
  prev:    `v_daily_minutes?select=minutes&day=gte.${d(PA)}&day=lte.${d(PB)}`,
  sess:    `sessions?select=completed&start_ts=gte.${t0(A)}&start_ts=lt.${t0(B + DAY)}`,
  low:     `events?select=id&type=eq.low_light&ts=gte.${t0(A)}&ts=lt.${t0(B + DAY)}`,
};
node.status({ fill: 'blue', shape: 'dot', text: `${kind} ${d(A)} → ${d(B)}` });
return [Object.entries(q).map(([kindReq, path]) => ({
  url: env.get('SUPABASE_URL') + '/rest/v1/' + path, method: 'GET', headers,
  kind: kindReq, reqId, requestTimeout: 10000 }))];

const st = flow.get('tkReq');
if (!st || msg.reqId !== st.id) return null;               // kết quả của lần tải cũ
let rows = msg.payload;
if (!(msg.statusCode >= 200 && msg.statusCode < 300) || !Array.isArray(rows)) {
  node.warn(`ID9 ${msg.kind}: HTTP ${msg.statusCode} ${JSON.stringify(msg.payload).slice(0, 150)}`);
  rows = [];
}
st.got[msg.kind] = rows;
if (Object.keys(st.got).length < 7) { flow.set('tkReq', st); return null; }
flow.set('tkReq', null);
const g = st.got, DAY = 86400000;
const days = [];
for (let t = Date.parse(st.A); t <= Date.parse(st.B); t += DAY) days.push(new Date(t).toISOString().slice(0, 10));
const TH = ['CN', 'T2', 'T3', 'T4', 'T5', 'T6', 'T7'];
const label = s => st.kind === 'tuan' ? TH[new Date(s).getUTCDay()] : String(+s.slice(8));
// 1. Phút học mỗi ngày (ngày không học = 0)
const m = {}; g.daily.forEach(r => m[r.day] = r.minutes);
const daily = days.map(s => ({ x: label(s), y: m[s] || 0 }));
// 2. Phút theo môn (cộng dồn cả khoảng)
const sm = {}; g.subject.forEach(r => sm[r.subject] = (sm[r.subject] || 0) + r.minutes);
const subject = Object.entries(sm).sort((a, b) => b[1] - a[1]).map(([x, y]) => ({ x, y }));
// 3. Kế hoạch so với thực tế (2 cột mỗi ngày)
const pv = {}; g.pva.forEach(r => pv[r.day] = r);
const pva = [];
days.forEach(s => {
  const r = pv[s] || { planned: 0, actual: 0 };
  pva.push({ x: label(s), y: r.planned, series: 'Kế hoạch' });
  pva.push({ x: label(s), y: r.actual, series: 'Thực tế' });
});
// 4. Độ sáng trung bình theo giờ 6h–23h
const lh = {}; g.lux.forEach(r => (lh[r.hour] = lh[r.hour] || []).push(r.lux_avg));
const lux = [];
for (let h = 6; h <= 23; h++) if (lh[h]) lux.push({ x: h + 'h', y: Math.round(lh[h].reduce((a, b) => a + b, 0) / lh[h].length) });
// Tổng kết
const tong = g.daily.reduce((a, r) => a + r.minutes, 0);
const truoc = g.prev.reduce((a, r) => a + r.minutes, 0);
const hm = p => `${Math.floor(p / 60)} giờ ${p % 60} phút`;
const ky = st.kind === 'tuan' ? 'tuần trước' : 'tháng trước';
const diff = tong - truoc, sign = diff > 0 ? '+' : '−';
const soSanh = diff === 0 ? `Bằng cùng kỳ ${ky}`
  : `${sign}${hm(Math.abs(diff))}${truoc ? ` (${sign}${Math.round(Math.abs(diff) / truoc * 100)}%)` : ''} so với cùng kỳ ${ky}`;
const n = g.sess.length, ok = g.sess.filter(r => r.completed).length;
const phien = n ? `${n} chu kỳ · ${Math.round(ok / n * 100)}% hoàn thành` : 'Chưa có chu kỳ nào';
node.status({ fill: 'green', shape: 'dot', text: `${st.A} → ${st.B}: ${tong} phút` });
const P = (payload, topic) => ({ payload, topic });
return [P(daily, 'Phút học'), P(subject, 'Phút học'), P(pva), P(lux, 'Độ sáng (%)'),
        P(hm(tong)), P(soSanh), P(phien), P(`${g.low.length} lần`)];

const SESSION_MIN = 90, STUDY_MIN = 25, BREAK_MIN = 5;   // 1 buổi 90 phút = 3 × (25 + 5)

const f = msg.payload || {};
const keys = ['t2', 't3', 't4', 't5', 't6', 't7', 'cn'];
const free_days = keys.map((k, i) => f[k] ? i : -1).filter(i => i >= 0);
const subjects = [], loi = [];
String(f.mon || '').split(/\r?\n/).forEach((line, i) => {
  const s = line.trim(); if (!s) return;
  const m = s.match(/^(.*?)[\s,;:]+(\d+)\s*(?:buổi|buoi)?\.?$/i);   // "Toán, 2" / "Toán 2" / "Toán 4 buổi"
  const name = (m ? m[1] : s).trim(), n = m ? +m[2] : 2;  // không ghi số buổi → 2
  if (!name || n < 1 || n > 7) loi.push(i + 1); else subjects.push({ name, sessions: n });
});
if (!free_days.length) return [null, { payload: 'Chọn ít nhất 1 ngày rảnh' }];
if (loi.length) return [null, { payload: `Dòng ${loi.join(', ')} sai: ghi "Tên môn, số buổi" (1–7)` }];
if (!subjects.length) return [null, { payload: 'Nhập môn cần học, mỗi dòng "Tên môn, số buổi"' }];
return [{ payload: { mode: 'free_days', free_days, subjects, priority: String(f.uutien || '').trim(),
                     session_min: SESSION_MIN, study_min: STUDY_MIN, break_min: BREAK_MIN } }, null];

const boDau = s => String(s).normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/đ/g, 'd').replace(/Đ/g, 'D');
const THU = ['Thứ 2', 'Thứ 3', 'Thứ 4', 'Thứ 5', 'Thứ 6', 'Thứ 7', 'Chủ nhật'];
// "2".."7", "T2", "Thứ 2", "CN", "Chủ nhật" -> 0..6 (0 = Thứ 2)
const parseThu = s => {
  const t = boDau(s).toLowerCase().replace(/\s+/g, '');
  if (t === 'cn' || t === 'chunhat' || t === '8') return 6;
  const m = t.match(/^(?:thu|t)?([2-7])$/);
  return m ? +m[1] - 2 : -1;
};
const parseGio = s => {
  const m = String(s || '').trim().match(/^(\d{1,2})[:h](\d{2})$/);
  if (!m || +m[1] > 23 || +m[2] > 59) return null;
  return m[1].padStart(2, '0') + ':' + m[2];
};
const toTable = tkb => tkb.map(r => ({ 'Thứ': THU[r.day], 'Bắt đầu': r.start, 'Kết thúc': r.end, 'Môn': r.subject }));

const f = msg.payload || {};
const day = parseThu(f.thu), start = parseGio(f.bd), end = parseGio(f.kt), subject = String(f.mon || '').trim();
if (day < 0 || !start || !end || start >= end || !subject)
  return [null, { payload: 'Tiết không hợp lệ: Thứ (2–7 hoặc CN), giờ bắt đầu < giờ kết thúc, có tên môn' }];
const tkb = flow.get('tkb') || [];
tkb.push({ day, start, end, subject });
tkb.sort((a, b) => a.day - b.day || a.start.localeCompare(b.start));
flow.set('tkb', tkb);
return [{ payload: toTable(tkb) }, { payload: `Đã thêm ${THU[day]} ${start}–${end} ${subject}` }];

const boDau = s => String(s).normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/đ/g, 'd').replace(/Đ/g, 'D');
const THU = ['Thứ 2', 'Thứ 3', 'Thứ 4', 'Thứ 5', 'Thứ 6', 'Thứ 7', 'Chủ nhật'];
// "2".."7", "T2", "Thứ 2", "CN", "Chủ nhật" -> 0..6 (0 = Thứ 2)
const parseThu = s => {
  const t = boDau(s).toLowerCase().replace(/\s+/g, '');
  if (t === 'cn' || t === 'chunhat' || t === '8') return 6;
  const m = t.match(/^(?:thu|t)?([2-7])$/);
  return m ? +m[1] - 2 : -1;
};
const parseGio = s => {
  const m = String(s || '').trim().match(/^(\d{1,2})[:h](\d{2})$/);
  if (!m || +m[1] > 23 || +m[2] > 59) return null;
  return m[1].padStart(2, '0') + ':' + m[2];
};
const toTable = tkb => tkb.map(r => ({ 'Thứ': THU[r.day], 'Bắt đầu': r.start, 'Kết thúc': r.end, 'Môn': r.subject }));

let p = msg.payload;
if (Buffer.isBuffer(p)) p = p.toString('utf8');
else if (p && p.type === 'Buffer' && Array.isArray(p.data)) p = Buffer.from(p.data).toString('utf8');
else if (p instanceof ArrayBuffer || ArrayBuffer.isView(p)) p = Buffer.from(p).toString('utf8');
else if (typeof p === 'string' && p.startsWith('data:')) p = Buffer.from(p.split(',')[1], 'base64').toString('utf8');
const lines = String(p || '').replace(/^\uFEFF/, '').split(/\r?\n/);
const tkb = [], loi = [];
lines.forEach((line, i) => {
  if (!line.trim()) return;
  const c = line.split(/[,;]/).map(s => s.trim());
  if (i === 0 && parseThu(c[0]) < 0 && /thu|day/i.test(boDau(c[0]))) return;   // dòng tiêu đề
  const day = parseThu(c[0]), start = parseGio(c[1]), end = parseGio(c[2]), subject = (c[3] || '').trim();
  if (c.length < 4 || day < 0 || !start || !end || start >= end || !subject) loi.push(i + 1);
  else tkb.push({ day, start, end, subject });
});
if (loi.length) return [null, { payload: `CSV sai ở dòng ${loi.join(', ')} – cần: thu,bat_dau,ket_thuc,mon (vd 2,07:30,11:30,Toán). Chưa nạp.` }];
if (!tkb.length) return [null, { payload: 'File CSV rỗng' }];
tkb.sort((a, b) => a.day - b.day || a.start.localeCompare(b.start));
flow.set('tkb', tkb);
return [{ payload: toTable(tkb) }, { payload: `Đã nạp ${tkb.length} tiết từ ${(msg.file && msg.file.name) || 'CSV'}` }];

if (msg.payload === 'clear') flow.set('tkb', []);
const THU = ['Thứ 2', 'Thứ 3', 'Thứ 4', 'Thứ 5', 'Thứ 6', 'Thứ 7', 'Chủ nhật'];
msg.payload = (flow.get('tkb') || []).map(r => ({ 'Thứ': THU[r.day], 'Bắt đầu': r.start, 'Kết thúc': r.end, 'Môn': r.subject }));
return msg;

const SESSION_MIN = 90, STUDY_MIN = 25, BREAK_MIN = 5;   // 1 buổi 90 phút = 3 × (25 + 5)

const tkb = flow.get('tkb') || [];
if (!tkb.length) return [null, { payload: 'Chưa có thời khóa biểu: thêm tiết hoặc tải CSV' }];
// Mỗi môn trên lớp: số buổi tự học = số tiết trong tuần (tối đa 3)
const dem = {}; tkb.forEach(r => dem[r.subject] = (dem[r.subject] || 0) + 1);
const subjects = Object.entries(dem).map(([name, n]) => ({ name, sessions: Math.min(3, n) }));
return [{ payload: { mode: 'timetable', timetable: tkb, subjects, priority: '',
                     session_min: SESSION_MIN, study_min: STUDY_MIN, break_min: BREAK_MIN } }, null];

const body = flow.get('aiLastReq');
if (!body) return [null, { payload: 'Chưa sinh lịch lần nào' }];
return [{ payload: body }, null];

flow.set('aiLastReq', msg.payload);
return { url: env.get('AI_URL') + '/schedule', method: 'POST', payload: msg.payload,
         headers: { 'Content-Type': 'application/json' }, kind: 'schedule', requestTimeout: 15000 };

// Lỗi kết nối (ECONNREFUSED, timeout…): statusCode là chữ, đã có catch báo lỗi
if (typeof msg.statusCode !== 'number') return null;
if (!(msg.statusCode >= 200 && msg.statusCode < 300) && !(msg.payload && msg.payload.message))
  return [null, null, null, { payload: `Dịch vụ AI trả lỗi HTTP ${msg.statusCode}` }];
if (msg.kind === 'schedule') return [msg, null, null, null];
if (msg.kind === 'scores') return [null, msg, null, null];
if (msg.kind === 'train') return [null, null, msg, null];
return null;

const d = msg.payload || {};
if (!d.ok) {
  flow.set('aiPlan', null);                              // không để lịch cũ gây nhầm
  const vnMsg = /^Khong xep duoc/.test(d.message || '')
    ? 'Không xếp được: giảm số buổi hoặc chọn thêm ngày rảnh (mỗi môn tối đa 1 buổi/ngày, mỗi ngày tối đa 3 buổi)'
    : (d.message || 'AI không xếp được lịch');
  return [{ payload: [] }, { payload: vnMsg }];
}
const THU = ['Thứ 2', 'Thứ 3', 'Thứ 4', 'Thứ 5', 'Thứ 6', 'Thứ 7', 'Chủ nhật'];
const vnReason = r => {
  let m = String(r).match(/^Truoc tiet (.+) (Thu [2-7]|Chu nhat)$/);
  if (m) return `Trước tiết ${m[1]} ${m[2] === 'Chu nhat' ? 'Chủ nhật' : m[2].replace('Thu', 'Thứ')}`;
  if (r === 'Mon uu tien') return 'Môn ưu tiên';
  m = String(r).match(/^Kha nang hoan thanh cao \((\d+)%\)$/);
  return m ? `Khả năng hoàn thành cao (${m[1]}%)` : r;
};
// Tuần áp dụng: T2–T6 → tuần này; T7, CN → tuần sau
const DAY = 86400000, vn = new Date(Date.now() + 7 * 3600000);
const today = Date.UTC(vn.getUTCFullYear(), vn.getUTCMonth(), vn.getUTCDate());
const wd = (vn.getUTCDay() + 6) % 7;                          // 0 = Thứ 2
const ws = today - wd * DAY + (wd >= 5 ? 7 * DAY : 0);
const iso = t => new Date(t).toISOString().slice(0, 10);
const req = flow.get('aiLastReq') || {};
const study = req.study_min || 25;
const rows = d.plan.map(p => ({
  week_start: iso(ws), day: iso(ws + p.day * DAY), start_time: p.start, end_time: p.end,
  subject: p.subject, cycles: p.cycles, score: p.score, reason: vnReason(p.reason) }));
flow.set('aiPlan', rows);
const dm = s => s.slice(8) + '/' + s.slice(5, 7);
const table = d.plan.map((p, i) => ({
  'Ngày': `${THU[p.day]} ${dm(rows[i].day)}`, 'Giờ': `${p.start}–${p.end}`, 'Môn': p.subject,
  'Số chu kỳ': `${p.cycles} × ${study} phút`, 'Khả năng hoàn thành': Math.round(p.score * 100) + '%',
  'Lý do': rows[i].reason }));
return [{ payload: table }, { payload: `AI xếp ${rows.length} buổi cho tuần ${dm(iso(ws))} – bấm "Lưu lịch" để lưu` }];

const SB = (path, method, body, extra) => {
  const key = env.get('SUPABASE_KEY');
  return Object.assign({
    url: env.get('SUPABASE_URL') + '/rest/v1/' + path, method: method || 'GET', payload: body,
    headers: Object.assign({ apikey: key, Authorization: 'Bearer ' + key, 'Content-Type': 'application/json' },
                           method === 'POST' ? { Prefer: 'return=minimal' } : {}),
    requestTimeout: 10000 }, extra || {});
};
const rows = flow.get('aiPlan');
if (!rows || !rows.length) return [null, { payload: 'Chưa có lịch để lưu – bấm "Sinh lịch tuần bằng AI" trước' }];
return [SB('plans?week_start=eq.' + rows[0].week_start, 'DELETE', undefined, { kind: 'del', rows }), null];

// Lỗi kết nối (ECONNREFUSED, timeout…): statusCode là chữ, đã có catch báo lỗi
if (typeof msg.statusCode !== 'number') return null;
const SB = (path, method, body, extra) => {
  const key = env.get('SUPABASE_KEY');
  return Object.assign({
    url: env.get('SUPABASE_URL') + '/rest/v1/' + path, method: method || 'GET', payload: body,
    headers: Object.assign({ apikey: key, Authorization: 'Bearer ' + key, 'Content-Type': 'application/json' },
                           method === 'POST' ? { Prefer: 'return=minimal' } : {}),
    requestTimeout: 10000 }, extra || {});
};
const ok = msg.statusCode >= 200 && msg.statusCode < 300;
if (!ok) {
  node.warn(`ID7 ${msg.kind}: HTTP ${msg.statusCode} ${JSON.stringify(msg.payload).slice(0, 200)}`);
  return [null, { payload: `Lỗi Supabase (${msg.kind}) HTTP ${msg.statusCode}` }, null];
}
if (msg.kind === 'del') return [SB('plans', 'POST', msg.rows, { kind: 'ins', n: msg.rows.length }), null, null];
if (msg.kind === 'ins') return [null, { payload: `Đã lưu ${msg.n} buổi vào bảng plans` }, null];
if (msg.kind === 'trainData') {
  const sessions = Array.isArray(msg.payload) ? msg.payload : [];
  return [null, null, { url: env.get('AI_URL') + '/train', method: 'POST', payload: { sessions },
                        headers: { 'Content-Type': 'application/json' }, kind: 'train', requestTimeout: 60000 }];
}
if (msg.kind === 'delOnly') return [null, { payload: `Đã xóa lịch tuần ${msg.ws.slice(8)}/${msg.ws.slice(5, 7)} (trên bảng và trong Supabase)` }, null];
return null;

const wd = (new Date(Date.now() + 7 * 3600000).getUTCDay() + 6) % 7;   // 0 = Thứ 2
return { url: `${env.get('AI_URL')}/scores?day=${wd}&session_min=90`, method: 'GET',
         kind: 'scores', requestTimeout: 8000 };

const d = msg.payload || {};
const chart = (d.scores || []).map(s => ({ x: s.hour + 'h', y: Math.round(s.p * 100) }));
const t = d.trained_at ? new Date(d.trained_at) : null;
const p2 = n => String(n).padStart(2, '0');
const vn = t ? new Date(t.getTime() + 7 * 3600000) : null;
const when = vn ? `${p2(vn.getUTCDate())}/${p2(vn.getUTCMonth() + 1)}/${vn.getUTCFullYear()} ${p2(vn.getUTCHours())}:${p2(vn.getUTCMinutes())}` : '—';
const acc = d.test_accuracy != null ? Math.round(d.test_accuracy * 100) + '%' : '—';
return [{ payload: chart, topic: 'Xác suất hoàn thành (%)' }, { payload: when }, { payload: acc }];

const SB = (path, method, body, extra) => {
  const key = env.get('SUPABASE_KEY');
  return Object.assign({
    url: env.get('SUPABASE_URL') + '/rest/v1/' + path, method: method || 'GET', payload: body,
    headers: Object.assign({ apikey: key, Authorization: 'Bearer ' + key, 'Content-Type': 'application/json' },
                           method === 'POST' ? { Prefer: 'return=minimal' } : {}),
    requestTimeout: 10000 }, extra || {});
};
return SB('sessions?select=start_ts,planned_min,focus_min,completed&dev=eq.pomo-01&order=start_ts', 'GET',
          undefined, { kind: 'trainData' });

const d = msg.payload || {};
