const out = [logMsg, null, { payload: `Gửi email lỗi (lần ${msg.attempt}/3): ${err}` }];
if (msg.attempt < 3) {
  const again = RED.util.cloneMessage(msg);
  delete again.error; again.attempt = msg.attempt + 1; again.delay = RETRY_MIN * 60000;
  out[1] = again;
  out[2].payload += ` – sẽ thử lại sau ${RETRY_MIN} phút`;
}
return out;

// $pageview: tải lại dữ liệu khi người dùng mở trang
if (msg.topic !== '$pageview') return null;
const path = (msg.payload && msg.payload.page && msg.payload.page.path) || '';
if (path === '/thong-ke') return [{ payload: 'refresh' }, null, null, null];
if (path === '/lich-hoc') return [null, { payload: 'refresh' }, null, null];
if (path === '/tong-quan') return [null, null, { payload: 'refresh' }, null];
if (path === '/cai-dat') return [null, null, null, { payload: 'refresh' }];
return null;
